        .app-shell{display:grid;grid-template-columns:205px minmax(0,1fr);min-height:100vh;max-width:1600px;margin:auto}.sidebar{position:sticky;top:0;display:flex;height:100vh;flex-direction:column;padding:21px 14px;border-right:1px solid var(--line);background:#0b1911da;backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:9px;padding:0 7px 22px;border-bottom:1px solid var(--line);font:700 18px Georgia,"Times New Roman",serif;text-decoration:none}.brand-mark{display:grid;place-items:center;width:31px;height:31px;border:1px solid #d4e5b264;border-radius:50% 50% 50% 12px;background:linear-gradient(145deg,#a9c77b,#436743);color:#132016;font-size:20px}.side-nav{display:grid;gap:5px;padding-top:18px}.side-nav a{display:flex;align-items:center;gap:10px;padding:10px 11px;border:1px solid transparent;border-radius:9px;color:#c6d0bf;text-decoration:none;font-size:12px;font-weight:600;transition:background .15s,border-color .15s}.side-nav a:hover,.side-nav a.active{border-color:#c9dda233;background:#dce9c818;color:#edf2dd}.side-nav a.active{box-shadow:inset 2px 0 #bad18c}.side-icon{display:grid;width:17px;place-items:center;color:#c6d99a;font-size:15px}.side-bottom{margin-top:auto;padding:15px 6px 2px;border-top:1px solid var(--line)}.side-user{display:flex;align-items:center;gap:9px;color:#e4e8d9;font-size:11px}.user-avatar{display:grid;place-items:center;width:30px;height:30px;border:1px solid #d2e0b760;border-radius:50%;background:linear-gradient(145deg,#809963,#314b30);color:#f6f2df;font-weight:800}.side-user small{display:block;color:#9eae9b;font-size:9px}
        .workspace{min-width:0}.topbar{display:flex;align-items:center;justify-content:flex-end;gap:12px;min-height:66px;padding:11px clamp(18px,4vw,54px);border-bottom:1px solid var(--line);background:#0d1a12a8;backdrop-filter:blur(12px)}.topbar-user{display:flex;align-items:center;gap:9px;color:#d2dacb;font-size:12px}.topbar .user-avatar{width:31px;height:31px}.signout{border:1px solid #dce8cb42;border-radius:9px;padding:7px 11px;background:#101f15;color:#eff0dc;font:inherit;font-size:11px;cursor:pointer}.signout:hover{background:#20341f}
