        .list{display:grid;gap:11px}.portfolio{display:grid;grid-template-columns:142px minmax(0,1fr) auto;align-items:center;gap:17px;padding:12px;border:1px solid #dce8cb36;border-radius:13px;background:linear-gradient(110deg,#10251adf,#0c1c13eF);box-shadow:0 9px 24px #0004;transition:border-color .16s,transform .16s}.portfolio:hover{transform:translateY(-1px);border-color:#c5dc9178}.portfolio-thumb{position:relative;display:grid;place-items:center;height:108px;overflow:hidden;border:1px solid #d7e6c784;border-radius:8px;background:linear-gradient(0deg,#10221571,#10221520),url('{{ asset('images/forest-hero.svg') }}') center 63%/cover}.portfolio-thumb:before{position:absolute;inset:0;background:linear-gradient(90deg,#08150b78,#14271820);content:""}.portfolio-thumb.thumb-modern{background-position:68% 53%}.portfolio-thumb.thumb-creative{background-position:35% 55%;filter:saturate(1.15)}.portfolio-thumb img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.thumb-initial{position:relative;display:grid;place-items:center;width:41px;height:41px;border:1px solid #e3edcfab;border-radius:50%;background:#263c29aa;color:#f1f2dd;font:700 19px Georgia,serif;box-shadow:0 3px 14px #0008}.thumb-caption{position:absolute;right:6px;bottom:5px;left:6px;overflow:hidden;color:#f5f1df;font:600 8px Georgia,serif;text-overflow:ellipsis;white-space:nowrap;text-shadow:0 1px 4px #000}
        .portfolio-main{display:flex;min-width:0;align-items:flex-start;gap:12px}.avatar{display:grid;flex:none;place-items:center;width:34px;height:34px;border:1px solid #cfe0a86a;border-radius:50%;background:linear-gradient(145deg,#829963,#314b30);color:#f5f1df;font-size:13px;font-weight:800}.portfolio-details{min-width:0}.name{overflow-wrap:anywhere;color:#f3f0df;font:600 16px/1.25 Georgia,"Times New Roman",serif}.meta{margin-top:4px;color:#bbc8b5;font-size:10px}.preview-links{display:flex;align-items:center;flex-wrap:wrap;gap:6px 11px;margin-top:8px;color:#aebba8;font-size:10px}.preview-links a{color:#d3e4a9;text-decoration:none;font-weight:650}.preview-links a:hover{text-decoration:underline}.status{display:inline-flex;align-items:center;gap:5px;border:1px solid #d7dfc630;border-radius:999px;padding:2px 7px;background:#5a2925a3;color:#ffd6ca;font-size:9px;font-weight:750}.status.is-published{border-color:#aac67853;background:#354b2ba8;color:#e2efbf}.public-url{flex:1 0 100%;max-width:100%;overflow-wrap:anywhere;color:#aebc9c;font-size:9px}.actions{display:flex;align-items:center;justify-content:flex-end;gap:6px;flex-wrap:wrap}.actions form{margin:0}.view-button,.edit-button,.delete,.publish{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-height:32px;border:1px solid #d7e4be4c;border-radius:8px;padding:6px 9px;background:#283f28;color:#f0efd9;text-decoration:none;font:inherit;font-size:10px;font-weight:700;cursor:pointer}.view-button:hover,.publish:hover{background:#3c5b34}.edit-button{background:#17291d}.edit-button:hover{background:#263c2b}.delete{border-color:#d1947963;background:#422d25;color:#ffe0d0}.delete:hover{background:#60362b}.publish{border-color:#d5e7a66a;background:#536e3c}
        .empty{padding:48px 22px;text-align:center;border:1px solid #dce8cb3d;border-radius:15px;background:#102218df;box-shadow:0 12px 32px #0004}.empty-mark{display:grid;place-items:center;width:51px;height:51px;margin:0 auto 12px;border:1px solid #d6e5ae52;border-radius:50%;background:#283d28;color:#d6e7a9;font-size:23px}.empty strong{display:block;margin-bottom:5px;color:#f2f0dd;font:600 19px Georgia,serif}.empty p{max-width:350px;margin:0 auto 17px;color:#c1cbb9;font-size:12px}
        body{background:linear-gradient(90deg,rgba(5,18,11,.72),rgba(7,19,12,.55) 48%,rgba(5,18,11,.67)),linear-gradient(0deg,rgba(4,13,8,.69),rgba(4,13,8,.10)),url('https://images.unsplash.com/photo-1774793846873-d922ef2733b1?auto=format&fit=crop&w=2200&q=80') center 58%/cover fixed no-repeat}body:before{display:none}.portfolio-thumb{background-image:linear-gradient(0deg,#10221571,#10221520),url('https://images.unsplash.com/photo-1774793846873-d922ef2733b1?auto=format&fit=crop&w=900&q=78');background-position:center 58%;background-size:cover}.portfolio-thumb.thumb-modern{background-position:center 53%}.portfolio-thumb.thumb-creative{background-position:center 62%;filter:saturate(1.08)}
        @media(max-width:900px){.app-shell{grid-template-columns:174px minmax(0,1fr)}.sidebar{padding-inline:10px}.portfolio{grid-template-columns:112px minmax(0,1fr);gap:12px}.portfolio-thumb{height:95px}.actions{grid-column:2;justify-content:flex-start}.portfolio-main{grid-column:2;grid-row:1}.portfolio-thumb{grid-column:1;grid-row:1/3}.portfolio{align-items:start}}
        @media(max-width:620px){.app-shell{display:block}.sidebar{position:relative;width:100%;height:auto;padding:10px 14px;border-right:0;border-bottom:1px solid var(--line)}.brand{padding:0 3px 9px;border:0}.side-nav{display:flex;gap:4px;overflow-x:auto;padding:2px 0 0}.side-nav a{flex:none;gap:6px;padding:7px 8px;font-size:10px}.side-icon{font-size:13px}.side-bottom{display:none}.topbar{min-height:49px;padding:7px 15px}.topbar-user{font-size:10px}main{padding:27px 14px 43px}.heading{align-items:flex-start;flex-direction:column;gap:13px;margin-bottom:17px}.heading .button{align-self:stretch}.portfolio{grid-template-columns:82px minmax(0,1fr);gap:10px;padding:9px}.portfolio-thumb{height:82px}.portfolio-main{gap:8px}.avatar{width:28px;height:28px;font-size:11px}.name{font-size:14px}.meta{font-size:9px}.preview-links{gap:5px 8px;font-size:9px}.actions{grid-column:1/-1;justify-content:flex-end;padding-top:8px;border-top:1px solid var(--line)}.view-button,.edit-button,.delete,.publish{min-height:31px;padding:5px 8px;font-size:9px}.public-url{font-size:8px}}
        @media(max-width:370px){.side-nav a{padding:6px;font-size:9px}.side-nav{gap:1px}.portfolio{grid-template-columns:69px minmax(0,1fr)}.portfolio-thumb{height:75px}.actions{justify-content:space-between}}
        @media(prefers-reduced-motion:reduce){.button,.portfolio{transition:none}}
        .view-button,.edit-button,.delete,.publish,.signout{min-height:40px;padding:8px 11px;font-size:11px;transition:background .15s,border-color .15s,transform .15s,filter .15s}
